        self.path = path

    def load(self) -> list[dict]:
        if not os.path.exists(self.path):
            return []
        try:
            with open(self.path, "r") as f:
                data = json.load(f)
            if not isinstance(data, list):
                raise ValueError("Invalid task data: expected a list")
            return data
        except (json.JSONDecodeError, ValueError) as e:
            raise ValueError(f"Failed to load tasks: {e}") from e

    def save(self, tasks: list[dict]):
        with open(self.path, "w") as f:
            json.dump(tasks, f, indent=2, ensure_ascii=False)

    def add(self, description: str) -> dict:
        tasks = self.load()
        new_id = max((t["id"] for t in tasks), default=0) + 1
        task = {
            "id": new_id,
            "description": description,
            "created_at": datetime.now().isoformat(),
            "done": False,
        }
        tasks.append(task)
        self.save(tasks)
        return task

    def get_by_id(self, task_id: int) -> dict | None:
        tasks = self.load()
        for task in tasks:
            if task["id"] == task_id:
                return task
        return None

    def list_tasks(self, include_done: bool = False) -> list[dict]:
        tasks = self.load()
        if include_done:
            return tasks
        return [t for t in tasks if not t["done"]]

    def mark_done(self, task_id: int) -> dict | None:
        tasks = self.load()
        for task in tasks:
            if task["id"] == task_id:
                task["done"] = True
                self.save(tasks)
                return task
        return None

    def delete(self, task_id: int) -> bool:
        tasks = self.load()
        for i, task in enumerate(tasks):
            if task["id"] == task_id:
                del tasks[i]
                self.save(tasks)
                return True
        return False


def main():
    parser = argparse.ArgumentParser(description="Simple task management CLI tool")
    subparsers = parser.add_subparsers(dest="command", required=True)

    parser_add = subparsers.add_parser("add", help="Add a new task")
    parser_add.add_argument("description", help="Task description")

    parser_list = subparsers.add_parser("list", help="List tasks")
    parser_list.add_argument("--all", action="store_true", help="Include completed tasks")

    parser_done = subparsers.add_parser("done", help="Mark a task as done")
    parser_done.add_argument("id", type=int, help="Task ID")

    parser_delete = subparsers.add_parser("delete", help="Delete a task")
    parser_delete.add_argument("id", type=int, help="Task ID")

    args = parser.parse_args()
    store = TaskStore()

    if args.command == "add":
        task = store.add(args.description)
        print(f"Added task {task['id']}: {task['description']}")

    elif args.command == "list":
        tasks = store.list_tasks(include_done=args.all)
        if not tasks:
            print("No tasks.")
        else:
            for t in tasks:
                suffix = " [done]" if t["done"] else ""
                print(f"{t['id']}: {t['description']}{suffix}")

    elif args.command == "done":
        task = store.mark_done(args.id)
        if task:
            print(f"Task {args.id} marked as done.")
        else:
            print("Task not found.", file=sys.stderr)
            sys.exit(1)

    elif args.command == "delete":
        if store.delete(args.id):
            print(f"Task {args.id} deleted.")
        else:
            print("Task not found.", file=sys.stderr)
            sys.exit(1)


if __name__ == "__main__":
    main()
